-- Backfill, by hand. Every user gets an owner profile named after them, and
-- everything that was "the user's" becomes the owner profile's. There is only
-- ever one user, but the owner lookups order by user_id so the result is
-- deterministic regardless. On a fresh install there are no users and every
-- statement below touches nothing.
INSERT INTO "profiles" ("user_id", "name", "is_owner") SELECT "id", "username", true FROM "users" ORDER BY "id";
--> statement-breakpoint
-- Signed-in sessions carry on as the owner rather than being sent to the
-- picker by an upgrade.
