-- Favourites, ratings and the vault move from the item to the owner's state.
-- Only items that had any of the three get a row: absence means "untouched".
INSERT INTO "profile_item_state" ("profile_id", "media_item_id", "is_favorite", "rating", "hidden_at")
SELECT o."id", m."id", m."is_favorite", m."rating", m."hidden_at"
FROM "media_items" m CROSS JOIN (SELECT "id" FROM "profiles" WHERE "is_owner" ORDER BY "user_id" LIMIT 1) o
WHERE m."is_favorite" OR m."rating" IS NOT NULL OR m."hidden_at" IS NOT NULL;
